FILE pantheon/src/review/identity.mjs
1: // MODEL IDENTITY for review independence (owner direction 2026-11-17: exclude the actual models that contributed to
2: // the reviewed work, not every model of their lab; keep three distinct labs on the panel).
3: //
4: // THE POLICY. Everything that decides "which model is this, and which lab made it" is one value, an identity policy
5: // (IDENTITY_POLICY_SCHEMA): the same-model map, the lab of every declared model, the lab of every direct vendor, the
6: // vendors that are routes, and the snapshot rule. `currentPolicy()` builds it from the configuration files. A cycle
7: // opened under pantheon.cycle/v3 RECORDS the whole policy with its digest (cycle-kinds.mjs), and every check of that
8: // cycle uses the recorded policy, never the files: editing the configuration cannot change how a recorded ledger
9: // verifies. A later correction is new evidence (`reassess`), recorded as such.
10: //
11: // RESOLUTION. `resolveModel(vendor, model, policy)` -> {id, lab, base, known, why}:
12: //   - the name is reduced to its base model: `same_model` (effort, thinking, lane and alias names), then a trailing
13: //     date snapshot (-YYYYMMDD) is dropped;
14: //   - the LAB is the base model's own (`model_lab`), whatever vendor or route reached it. It is never inferred from
15: //     the transport: a model the policy does not declare is UNRESOLVED (known: false, lab: null, id: null);
16: //   - a direct vendor (not a route) can only serve its own lab's models; any other pairing is unresolved.
17: // An unresolved name is never treated as a different model, and never as a model of the vendor's lab.
18: //
19: // Must never: treat two effort levels, aliases, snapshots, sessions or routes of one model as two reviewers; take a
20: // model's lab from the route that served it; qualify a reviewer whose identity is unresolved; or let the current
21: // configuration change the verdict on a recorded cycle.
22: import { readFileSync } from "node:fs";
23: import { dirname, join } from "node:path";
24: import { fileURLToPath } from "node:url";
25: import { createHash } from "node:crypto";
26: import { canonical } from "../../../packages/ledger/canonical.mjs";
27: import { MODELS, LANES } from "../config/models.mjs";
28: 
29: export const IDENTITY_POLICY_SCHEMA = "pantheon.identity-policy/v1";
30: const FILE = join(dirname(fileURLToPath(import.meta.url)), "../config/model-identity.json");
31: const str = v => typeof v === "string" && v.trim() !== "";
32: const SNAPSHOT = /-\d{8}$/;
33: // The policy's `resolver` number is the version of its ADMISSION rule, pinned with the rest on each cycle:
34: //   1  (cycles recorded before the review of 10cbd52) an answer that names no serving model was taken to have been
35: //      served by the model asked for. Kept only so those cycles verify as they were recorded.
36: //   2  an answer is admitted only on the identity of the model that ANSWERED: a missing, blank or unresolved
37: //      serving model does not qualify, and the model asked for is never evidence of which model answered.
38: //   3  (owner direction 2026-11-17) as 2, and a ROUTE is seated only for the labs the policy lists for it
39: //      (`route_labs`): Antigravity serves Gemini models only. A seat on a route for a model of any other lab is not
40: //      asked and its answer is not admitted. Contributors are still resolved by model, whatever route reached them.
41: export const RESOLVER = 3;
42: export const RESOLVERS = Object.freeze([1, 2, 3]);
43: 
44: /** A base model name under `policy`: lower case, through `same_model`, without a date snapshot (applied to a fixpoint). */
45: function baseOf(model, policy) {
46:   let m = String(model).trim().toLowerCase();
47:   for (let i = 0; i < 8; i++) {
48:     const next = (policy.same_model[m] ?? m).replace(SNAPSHOT, "");
49:     if (next === m) break;
50:     m = next;
51:   }
52:   return m;
53: }
54: 
55: /** The policy the configuration files describe now. Built once per process. */
56: function build() {
57:   const rules = JSON.parse(readFileSync(FILE, "utf8"));
58:   const same_model = Object.fromEntries(Object.entries(rules.same_model ?? {}).map(([k, v]) => [k.toLowerCase(), String(v.model).toLowerCase()]));
59:   const routes = [...(rules.routes ?? [])].sort();
60:   const bare = { same_model };
61:   const model_lab = {};
62:   const declare = (model, lab, from) => {
63:     const b = baseOf(model, bare);
64:     if (model_lab[b] && model_lab[b] !== lab) throw new Error(`identity policy: ${b} is declared for ${model_lab[b]} and for ${lab} (${from})`);
65:     model_lab[b] = lab;
66:   };
67:   for (const [m, lab] of Object.entries(rules.model_lab ?? {})) declare(m, lab, "model-identity.json");
68:   // models.json: a vendor's own registry. A route has no registry of its own models here.
69:   for (const [vendor, names] of Object.entries(MODELS)) for (const id of Object.values(names)) declare(id, vendor, "models.json");
70:   // lanes.json: each lane model names its lab.
71:   for (const lane of Object.values(LANES)) for (const [m, spec] of Object.entries(lane)) declare(m, spec.lab, "lanes.json");
72:   const vendor_lab = Object.fromEntries(Object.keys(MODELS).filter(v => !routes.includes(v)).sort().map(v => [v, v]));
73:   const route_labs = Object.fromEntries(Object.entries(rules.route_labs ?? {}).sort().map(([v, labs]) => [v, [...labs].sort()]));
74:   for (const v of Object.keys(route_labs)) if (!routes.includes(v)) throw new Error(`identity policy: route_labs names ${v}, which is not a route`);
75:   const policy = { schema: IDENTITY_POLICY_SCHEMA, resolver: RESOLVER, snapshot: "-YYYYMMDD", same_model, model_lab: Object.fromEntries(Object.entries(model_lab).sort()), vendor_lab, routes, route_labs };
76:   return Object.freeze(policy);
77: }
78: let CURRENT = null;
79: export const currentPolicy = () => (CURRENT ??= build());
80: export const policyDigest = policy => "sha256:" + createHash("sha256").update(canonical(policy)).digest("hex");
81: /** Why `policy` is not a usable identity policy, or null. */
82: export function policyRefusal(policy) {
83:   const map = (o, ok) => o && typeof o === "object" && !Array.isArray(o) && Object.entries(o).every(([k, v]) => str(k) && ok(v));
84:   return policy?.schema === IDENTITY_POLICY_SCHEMA && RESOLVERS.includes(policy.resolver) && map(policy.same_model, str) && map(policy.model_lab, str)
85:     && map(policy.vendor_lab, str) && Array.isArray(policy.routes) && policy.routes.every(str)
86:     && (policy.resolver >= 3 ? map(policy.route_labs, v => Array.isArray(v) && v.every(str)) : policy.route_labs === undefined) ? null
87:     : `an identity policy is a ${IDENTITY_POLICY_SCHEMA} object {resolver, same_model, model_lab, vendor_lab, routes} (and route_labs from resolver 3)`;
88: }
89: 
90: /** Resolve a model reached through `vendor`. Unresolved: {known: false, id: null, lab: null, why}. */
91: export function resolveModel(vendor, model, policy = currentPolicy()) {
92:   if (!str(model)) return null;
93:   const base = baseOf(model, policy), lab = policy.model_lab[base] ?? null;
94:   const no = why => ({ id: null, lab: null, base, known: false, why });
95:   if (!lab) return no(`"${model}" is not a model this identity policy declares: its lab is not inferred from the ${vendor ?? "unknown"} route`);
96:   if (str(vendor) && !policy.routes.includes(vendor)) {
97:     const own = policy.vendor_lab[vendor] ?? null;
98:     if (!own) return no(`"${vendor}" is not a vendor this identity policy declares`);
99:     if (own !== lab) return no(`${base} is a ${lab} model and cannot have been served by the ${vendor} vendor directly`);
100:   }
101:   return { id: `${lab}/${base}`, lab, base, known: true, why: null };
102: }
103: /** Kept name: the identity of a model (see resolveModel). */
104: export const modelIdentity = resolveModel;
105: 
106: /** Why a seat on `vendor` may not be seated for a model of `lab` under `policy` (resolver 3: route_labs), or null. */
107: function routeRefusal(vendor, lab, policy) {
108:   const allowed = policy.route_labs?.[vendor];
109:   return allowed && !allowed.includes(lab) ? `the ${vendor} route is seated for ${allowed.join(", ")} models only, and this is a ${lab} model` : null;
110: }
111: 
112: /**
113:  * What a set of contributions excludes from reviewing:
114:  *   models      the contributing models, by identity (the requested and the served model of a turn both count);
115:  *   labs        the labs of contributions that name a lab and no model (an explicit lab, not an inference);
116:  *   unresolved  contributions whose model name the policy cannot resolve. Nothing can be said about who may review
117:  *               such work, so no panel qualifies until the name is declared.
118:  * Returns {models, labs, unresolved, contributing_labs}, sorted.
119:  */
120: export function contributorKeys(contributions = [], policy = currentPolicy()) {
121:   const models = new Set(), labs = new Set(), all = new Set(), unresolved = new Map();
122:   for (const c of contributions) {
123:     const names = [...new Set([c.model, c.served_model, c.requested_model].filter(str))];
124:     if (!names.length) { if (str(c.lab)) { labs.add(c.lab); all.add(c.lab); } else unresolved.set(`${c.vendor ?? "?"}/-`, { vendor: c.vendor ?? null, model: null, why: "a contribution that names neither a model nor a lab" }); continue; }
125:     for (const m of names) {
126:       const r = resolveModel(c.vendor, m, policy);
127:       if (r.known) { models.add(r.id); all.add(r.lab); } else unresolved.set(`${c.vendor ?? "?"}/${m}`, { vendor: c.vendor ?? null, model: m, why: r.why });
128:     }
129:   }
130:   return { models: [...models].sort(), labs: [...labs].sort(), unresolved: [...unresolved.values()], contributing_labs: [...all].sort() };
131: }
132: 
133: /**
134:  * BEFORE A CALL: may this seat be ASKED? Only the model asked for is known. It must resolve, and must not be a
135:  * contributor. Returns {lab, id} or {why, code}.
136:  */
137: export function candidateIdentity(seat, policy = currentPolicy()) {
138:   const asked = resolveModel(seat.vendor, seat.model, policy);
139:   if (!asked?.known) return { code: "UNRESOLVED", why: `the seat's identity is unresolved: ${asked?.why ?? "no model is named"}` };
140:   const route = routeRefusal(seat.vendor, asked.lab, policy);
141:   if (route) return { code: "ROUTE_LAB", why: route };
142:   return { lab: asked.lab, id: asked.id };
143: }
144: /** Why `seat` ({vendor, model}) may not be asked to review work with contributor `keys`, or null. */
145: export function candidateRefusal(seat, keys, policy = currentPolicy()) {
146:   if ((keys.unresolved ?? []).length) return `a contributor's identity is unresolved (${keys.unresolved.map(u => u.model ?? u.vendor).join(", ")}): no reviewer can be shown not to be it`;
147:   const who = candidateIdentity(seat, policy);
148:   if (who.why) return who.why;
149:   if ((keys.labs ?? []).includes(who.lab)) return `the ${who.lab} lab is excluded: a contribution from it names no model`;
150:   return (keys.models ?? []).includes(who.id) ? `${who.id} contributed to the change under review and may not review it` : null;
151: }
152: 
153: /**
154:  * AFTER A CALL: the identity an ANSWER is admitted under, or why it is not. `answer` is {vendor, model, served_model}:
155:  * the model asked for and the model that answered. Both must resolve, to the SAME lab; the lab a review counts for is
156:  * that lab. Under resolver 2 the serving model must be NAMED: the model asked for is not evidence of which model
157:  * answered. Returns {lab, ids} or {why, code}.
158:  */
159: export function reviewerIdentity(answer, policy = currentPolicy()) {
160:   const asked = resolveModel(answer.vendor, answer.model, policy);
161:   if (!asked?.known) return { code: "UNRESOLVED", why: `the reviewer's identity is unresolved: ${asked?.why ?? "no model is named"}` };
162:   const route = routeRefusal(answer.vendor, asked.lab, policy);
163:   if (route) return { code: "ROUTE_LAB", why: route };
164:   let served;
165:   if (str(answer.served_model)) served = resolveModel(answer.vendor, answer.served_model, policy);
166:   else if (policy.resolver >= 2) return { code: "NO_SERVED_IDENTITY", why: `the answer names no serving model: ${asked.id} was asked, and that is not evidence of which model answered` };
167:   else served = asked;   // resolver 1, for cycles recorded under it
168:   if (!served.known) return { code: "UNRESOLVED", why: `the model that answered is unresolved: ${served.why}` };
169:   if (served.lab !== asked.lab) return { code: "LAB_MISMATCH", why: `${asked.id} was asked and ${served.id} answered: a review counts for one lab` };
170:   return { lab: served.lab, ids: [...new Set([asked.id, served.id])] };
171: }
172: 
173: /** Why an ANSWER may not count as a review of work with contributor `keys` ({models, labs, unresolved?}), or null. */
174: export function reviewerRefusal(answer, keys, policy = currentPolicy()) {
175:   if ((keys.unresolved ?? []).length) return `a contributor's identity is unresolved (${keys.unresolved.map(u => u.model ?? u.vendor).join(", ")}): no reviewer can be shown not to be it`;
176:   const who = reviewerIdentity(answer, policy);
177:   if (who.why) return who.why;
178:   if ((keys.labs ?? []).includes(who.lab)) return `the ${who.lab} lab is excluded: a contribution from it names no model`;
179:   const hit = who.ids.find(i => (keys.models ?? []).includes(i));
180:   return hit ? `${hit} contributed to the change under review and may not review it` : null;
181: }
182: 
183: /**
184:  * NEW EVIDENCE, never a change of history: which recorded reviews of a v3 cycle would not qualify under another
185:  * policy (by default the current one). `reviews` are {seat: {vendor}, model, served_model, hash}; `cycle` the cycle
186:  * payload. Returns {policy: digest, recorded: digest, changed, findings: [{review, why}]}.
187:  */
188: export function reassess({ cycle, reviews, policy = currentPolicy() }) {
189:   const keys = contributorKeys(cycle.contributors ?? [], policy);
190:   const findings = [];
191:   for (const r of reviews) {
192:     const why = reviewerRefusal({ vendor: r.seat.vendor, model: r.model, served_model: r.served_model ?? null }, keys, policy);
193:     if (why) findings.push({ review: r.hash, why });
194:   }
195:   const labsNow = reviews.map(r => reviewerIdentity({ vendor: r.seat.vendor, model: r.model, served_model: r.served_model ?? null }, policy).lab ?? null);
196:   if (new Set(labsNow.filter(Boolean)).size < labsNow.length && !findings.length) findings.push({ review: null, why: "under this policy two of the reviews count for one lab" });
197:   return { policy: policyDigest(policy), recorded: cycle.identity_policy?.digest ?? null, changed: policyDigest(policy) !== (cycle.identity_policy?.digest ?? null), findings };
198: }
199: 

