FILE pantheon/src/pipeline/dispatch.mjs
1: // STAGE 2: DISPATCH. Two parts, kept apart on purpose.
2: //
3: //  (1) The Dispatcher SPECIALIST — one read-only model turn per unit. It judges whether the unit is cohesive,
4: //      confirms or corrects `specialist_role`, may RAISE (never lower) `difficulty`, and writes the acceptance
5: //      rubric. The controller then FREEZES that rubric: rubric_hash = sha256(canonical {unit_id, owned_paths,
6: //      verify_cmd, invariants, rubric}). Stage 5 re-hashes it before every review.
7: //  (2) The deterministic CONTROLLER ({vendor: "controller"}, no model) — disjoint owned-path locks, topological
8: //      waves, and one isolated git worktree per active unit.
9: //
10: // OWNER GOVERNANCE DECISION (2026-11-17) — FOR INDEPENDENT REVIEW. Stage 2 is recorded as a NON-AUTHORING ARBITER
11: // ({role: "dispatcher", standing: "arbiter", authored: false}). The dispatcher shapes the rubric but writes none of
12: // the work, so it is NOT listed among the contributions (record.mjs: contributionsOf) and, under model-level review
13: // independence, the exact Stage 2 model is permitted — and PINNED — to perform the Stage 5 review of the same unit.
14: // This is a decision of the owner, not a consequence of the code: a reader who holds that writing the acceptance
15: // criteria is a contribution to the change will disagree with it, and should. arbitersOf(run) lists every such seat
16: // so that position can be checked against a recorded run.
17: //
18: // Inputs: validated work units, an INJECTED seat and turn. Outputs: dispatch records, waves, worktree bindings.
19: //
20: // Must never: let the dispatcher lower a difficulty, dispatch a non-cohesive unit, put two units with overlapping
21: // owned paths in one wave, bind two units to one worktree, or run git synchronously.
22: import { rm } from "node:fs/promises";
23: import { CAPABILITIES, digestOf, judgingTurn, keysRefusal, str, clone } from "./util.mjs";
24: import { pathsOverlap as overlapOf } from "./paths.mjs";
25: import { DIFFICULTIES, cycleOf } from "./work-units.mjs";
26: import { git } from "./git.mjs";
27: 
28: export const CONTROLLER = Object.freeze({ vendor: "controller", model: null });
29: export const pathsOverlap = overlapOf;
30: const byId = (a, b) => (a.unit_id < b.unit_id ? -1 : a.unit_id > b.unit_id ? 1 : 0);
31: 
32: // ---------------------------------------------------------------------------------------------- the specialist
33: 
34: export const DISPATCH_KEYS = Object.freeze(["unit_id", "cohesive", "specialist_role", "difficulty", "rubric", "notes"]);
35: export const DISPATCH_SCHEMA = Object.freeze({
36:   $id: "pantheon.pipeline.dispatch/v1",
37:   type: "object",
38:   additionalProperties: false,
39:   required: [...DISPATCH_KEYS],
40:   properties: {
41:     unit_id: { type: "string" },
42:     cohesive: { type: "boolean" },
43:     specialist_role: { type: "string", minLength: 1 },
44:     difficulty: { enum: [...DIFFICULTIES] },
45:     rubric: { type: "array", minItems: 1, items: { type: "string", minLength: 1 }, uniqueItems: true },
46:     notes: { type: "string" },
47:   },
48: });
49: 
50: export function DISPATCHER_PROMPT({ unit, plan }) {
51:   const others = (plan ?? []).filter(u => u.unit_id !== unit.unit_id).map(u => `- ${u.unit_id}: owns ${u.owned_paths.join(", ")}; depends on ${u.depends_on.join(", ") || "nothing"}`);
52:   return [
53:     "ROLE: dispatcher for a supervised build pipeline. You are a READ-ONLY specialist and an ARBITER: you judge one work unit and write its acceptance rubric. You write none of the work, edit no file and run no command.",
54:     "",
55:     "THE UNIT",
56:     JSON.stringify(unit, null, 2),
57:     "",
58:     others.length ? `THE OTHER UNITS OF THE PLAN\n${others.join("\n")}\n` : "",
59:     "DECIDE",
60:     "1. cohesive — true only if this unit holds everything that is coupled: its types, the implementation that uses them and the tests that prove them are all inside its owned_paths, and its verify_cmd can pass on top of its depends_on alone. If a coupled file belongs to another unit, or the unit is several unrelated changes, answer false and say what must move in `notes`: the unit goes back to the planner.",
61:     "2. specialist_role — confirm the planner's, or correct it to the kind of engineer this unit really needs.",
62:     `3. difficulty — confirm "${unit.difficulty}" or RAISE it. You may not lower it; a lower answer is refused.`,
63:     "4. rubric — the acceptance criteria a reviewer will later check one by one against the diff and the verify_cmd output. Each is one checkable sentence. Cover every invariant. Do not restate the same criterion twice. This rubric is frozen and hashed when you answer.",
64:     "",
65:     "OUTPUT: exactly one JSON object and nothing else (no prose, no code fence):",
66:     `{"unit_id":"${unit.unit_id}","cohesive":true,"specialist_role":"string","difficulty":"easy | medium | hard","rubric":["acceptance criterion"],"notes":"string"}`,
67:     "Any other key, a missing key, or text outside the object is refused.",
68:   ].filter(l => l !== "").join("\n");
69: }
70: 
71: /** Why a dispatcher answer is not admitted for `unit`, as {code, why}, or null. */
72: export function dispatchRefusal(d, unit) {
73:   const keys = keysRefusal(d, [...DISPATCH_KEYS]);
74:   if (keys) return { code: "SCHEMA", why: `dispatch answer: ${keys}` };
75:   if (d.unit_id !== unit.unit_id) return { code: "SCHEMA", why: `dispatch answer is for "${d.unit_id}", not "${unit.unit_id}"` };
76:   if (typeof d.cohesive !== "boolean") return { code: "SCHEMA", why: "cohesive is a boolean" };
77:   if (!str(d.specialist_role)) return { code: "SCHEMA", why: "specialist_role is a non-empty string" };
78:   if (!DIFFICULTIES.includes(d.difficulty)) return { code: "SCHEMA", why: `difficulty is one of ${DIFFICULTIES.join(", ")}` };
79:   if (typeof d.notes !== "string") return { code: "SCHEMA", why: "notes is a string" };
80:   if (!Array.isArray(d.rubric) || !d.rubric.length || !d.rubric.every(str)) return { code: "SCHEMA", why: "rubric is a non-empty array of non-empty strings" };
81:   if (new Set(d.rubric).size !== d.rubric.length) return { code: "SCHEMA", why: "rubric repeats a criterion" };
82:   if (DIFFICULTIES.indexOf(d.difficulty) < DIFFICULTIES.indexOf(unit.difficulty)) return { code: "DIFFICULTY_LOWERED", why: `the dispatcher may raise or keep a difficulty, never lower it: planned ${unit.difficulty}, answered ${d.difficulty}` };
83:   return null;
84: }
85: 
86: /** The frozen acceptance rubric's hash. The five fields are everything a review is judged against. */
87: export const rubricHash = ({ unit_id, owned_paths, verify_cmd, invariants, rubric }) => digestOf({ unit_id, owned_paths, verify_cmd, invariants, rubric });
88: 
89: /**
90:  * Run the dispatcher turn for one unit and freeze its rubric.
91:  * turn({vendor, model, prompt, seat, schema, sandbox, role: "dispatcher", unit_id, signal}) -> {text, served_model}
92:  * Returns the unit's DISPATCH RECORD:
93:  *   {role: "dispatcher", standing: "arbiter", authored: false, vendor, model, served_model, served_model_source,
94:  *    status: "dispatched" | "returned" | "blocked", code, why, cohesive, specialist_role, difficulty,
95:  *    planned_difficulty, rubric, rubric_hash, notes, attempts}
96:  * "returned": the unit is not cohesive and goes back to the planner. "blocked": no answer was admitted.
97:  */
98: export async function runDispatcher({ unit, plan = [], seat, turn, signal, sameModel }) {
99:   const rec = { role: "dispatcher", standing: "arbiter", authored: false, vendor: seat.vendor, model: seat.model, served_model: null, served_model_source: null,
100:     status: "blocked", code: null, why: null, cohesive: null, specialist_role: null, difficulty: null, planned_difficulty: unit.difficulty, rubric: null, rubric_hash: null, notes: null, attempts: [] };
101:   const r = await judgingTurn({ seat, turn, sameModel, admit: v => dispatchRefusal(v, unit),
102:     args: { vendor: seat.vendor, model: seat.model, seat: clone(seat), prompt: DISPATCHER_PROMPT({ unit, plan }), schema: DISPATCH_SCHEMA, sandbox: CAPABILITIES.dispatcher, role: "dispatcher", unit_id: unit.unit_id, signal } });
103:   rec.attempts = r.attempts;
104:   if (!r.admitted) return Object.assign(rec, { code: r.code, why: `no dispatcher answer was admitted: ${r.why}` });
105:   const d = r.value;
106:   Object.assign(rec, { served_model: r.served_model, served_model_source: r.served_model_source, cohesive: d.cohesive, specialist_role: d.specialist_role, difficulty: d.difficulty, rubric: [...d.rubric], notes: d.notes });
107:   rec.rubric_hash = rubricHash({ unit_id: unit.unit_id, owned_paths: unit.owned_paths, verify_cmd: unit.verify_cmd, invariants: unit.invariants, rubric: rec.rubric });
