1: // REASSESSMENT of an item's recorded reviews under a later identity policy (pantheon review/identity.mjs `reassess`).
2: //
3: // A pantheon.cycle/v3 cycle is verified, always, under the identity policy it recorded. When the rules are later
4: // corrected (an alias found, a lab mapping fixed), an already recorded review may turn out to have been given by a
5: // model that contributed. That is NEW EVIDENCE: this module finds it and records it on the work ledger
6: // (work.reassessment), with the corrected policy itself. Recording it changes nothing in the cycle's ledger and
7: // nothing on the status ledger. What it changes is forward progress (gates.mjs): a disqualified approval, and the
8: // validation and outcome resting on it, are not reused; active work is routed to a bounded re-review; a Resolved
9: // item is marked as needing re-verification, for the owner.
10: //
11: // Inputs: the work ledger, an item, and the policy to reassess under (default: the current one). Returns what it
12: // recorded. Must never: write to a review ledger or the status ledger, or record the same reassessment twice.
13: import {openPantheonLedger} from '../../pantheon/src/ledger/system.mjs';
14: import {reassess, currentPolicy, policyDigest} from '../../pantheon/src/review/identity.mjs';
15: 
16: /** The review cycles an item's passed stages rest on: [{stage, record, cycle, ledger, anchor}]. */
17: export function cyclesOf(work, item) {
18:   const out = [];
19:   for (const s of work.stages(item)) {
20:     if (s.status !== 'passed') continue;
21:     if (s.stage === 'plan' && s.outputs?.plan_review?.cycle) out.push({stage: 'plan', record: s.hash, cycle: s.outputs.plan_review.cycle, ledger: s.outputs.plan_ledger ?? null, anchor: s.outputs.plan_review.ledger_anchor ?? null});
22:     if (s.stage === 'review' && s.outputs?.cycle) out.push({stage: 'review', record: s.hash, cycle: s.outputs.cycle, ledger: s.outputs.cycle_ledger ?? null, anchor: s.outputs.cycle_ledger_anchor ?? null});
23:   }
24:   return out;
25: }
26: 
27: /**
28:  * Reassess every model-rule cycle of `item` under `policy` and record each one that has findings (once per cycle
29:  * and policy). Cycles opened under the lab rule carry no identity policy and are not reassessed.
30:  */
31: export function reassessItem({work, item, policy = currentPolicy(), at = new Date().toISOString()}) {
32:   const digest = policyDigest(policy), done = new Set(work.reassessments(item).map(r => `${r.cycle}|${r.policy}`));
33:   const recorded = [], skipped = [];
34:   for (const c of cyclesOf(work, item)) {
35:     if (!c.ledger) { skipped.push({...c, why: 'the stage record does not say where its review ledger is'}); continue; }
36:     const sys = openPantheonLedger({root: c.ledger, anchor: c.anchor});
37:     const state = sys.recorder().cycleState(c.cycle);
38:     if (state.cycle.contract !== 'pantheon.cycle/v3') { skipped.push({...c, why: 'opened under the lab rule: no identity policy to reassess'}); continue; }
39:     const r = reassess({cycle: state.cycle, reviews: state.reviews, policy});
40:     if (!r.changed || !r.findings.length) { skipped.push({...c, why: r.changed ? 'no recorded review is disqualified under this policy' : 'this is the policy the cycle recorded'}); continue; }
41:     if (done.has(`${c.cycle}|${digest}`)) { skipped.push({...c, why: 'already recorded'}); continue; }
42:     const hash = work.recordReassessment({item, cycle: c.cycle, recorded_policy: r.recorded, policy: digest, findings: r.findings, policy_rules: policy, at});
43:     recorded.push({...c, reassessment: hash, findings: r.findings});
44:   }
45:   return {item, policy: digest, recorded, skipped};
46: }
